      {keepouts&&(boardDef.keepouts||[]).map(k=><polygon className="keepout" key={k.id} points={pts(k.polygon)}><title>{k.kind} keepout</title></polygon>)}
      {boardDef.traces.filter(t=>layerVisible(t.layer)).map(t=><g key={t.id} className="trace-object" data-selected={selected===`trace:${t.id}`} onClick={event=>{if(mode==="select"){event.stopPropagation();setSelected(`trace:${t.id}`)}}}><polyline points={pts(t.points)} fill="none" stroke="#1a0b04" strokeOpacity=".75" strokeWidth={mm(t.width_nm)+.16} strokeLinecap="round" strokeLinejoin="round"/><polyline className="trace" data-layer={t.layer} points={pts(t.points)} fill="none" strokeWidth={mm(t.width_nm)} strokeLinecap="round" strokeLinejoin="round" strokeDasharray={t.layer==="B.Cu"?".55 .22":undefined}><title>{netNames[t.net_id]} · {t.layer} · {mm(t.width_nm)} mm</title></polyline></g>)}
