      {boardDef.vias.map(v=><g className="via-object" data-selected={selected===`via:${v.id}`} key={v.id} onClick={event=>{if(mode==="select"){event.stopPropagation();setSelected(`via:${v.id}`)}}}><circle cx={mm(v.x_nm)} cy={mm(v.y_nm)} r={mm(v.diameter_nm)/2} fill="#d9b45b" stroke="#5d3f12" strokeWidth=".08"/><circle cx={mm(v.x_nm)} cy={mm(v.y_nm)} r={mm(v.drill_nm)/2} fill="#1a0b04"/><title>{netNames[v.net_id]} via · drill {mm(v.drill_nm)} mm</title></g>)}
